def merge_coverage(periods):
    if not periods:
        return []
    periods = sorted(periods)          # sorts by start, then end
    out = [list(periods[0])]
    for start, end in periods[1:]:
        if start <= out[-1][1]:        # overlaps or touches the last merged one
            out[-1][1] = max(out[-1][1], end)
        else:
            out.append([start, end])
    return out

